const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000
const MONTH_IN_MILLISECONDS = 30 * DAY_IN_MILLISECONDS
const YEAR_IN_MILLISECONDS = 365 * DAY_IN_MILLISECONDS
const locale = document.documentElement.lang || undefined

const relativeFormatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })
const timeFormatter = new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" })
const shortDateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" })
const dateFormatter = new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", year: "numeric" })
const longDateFormatter = new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" })
const numericDateTimeFormatter = new Intl.DateTimeFormat(locale, {
  month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
})

export function signedDifferenceInDays(fromDate, toDate) {
  return localDateOrdinal(toDate) - localDateOrdinal(fromDate)
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function formatLocalTime(date, format = "smart", now = new Date()) {
  switch (format) {
    case "time":
      return timeFormatter.format(date)
    case "short-date":
      return shortDateFormatter.format(date)
    case "date":
      return dateFormatter.format(date)
    case "long-date":
      return longDateFormatter.format(date)
    case "numeric-date-time":
      return numericDateTimeFormatter.format(date)
    case "relative":
      return formatRelative(date, now)
    case "calendar-relative":
      return relativeFormatter.format(signedDifferenceInDays(now, date), "day")
    case "smart":
      return formatSmart(date, now)
    default:
      return dateFormatter.format(date)
  }
}

export function dateFromDateTime(value) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const [year, month, day] = value.split("-").map(Number)
    const date = new Date(0)
    date.setFullYear(year, month - 1, day)
    date.setHours(0, 0, 0, 0)
    return date
  }

  return new Date(value)
}

function formatSmart(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return timeFormatter.format(date)
  } else if (Math.abs(days) <= 6) {
    return relativeFormatter.format(days, "day")
  } else if (date.getFullYear() === now.getFullYear()) {
    return shortDateFormatter.format(date)
  } else {
    return dateFormatter.format(date)
  }
}

function formatRelative(date, now) {
  const difference = date.getTime() - now.getTime()
  const absoluteDifference = Math.abs(difference)

  if (absoluteDifference < 60 * 1000) {
    return difference < 0 ? "just now" : relativeFormatter.format(Math.max(1, Math.round(difference / 1000)), "second")
  } else if (absoluteDifference < 60 * 60 * 1000) {
    return relativeFormatter.format(Math.round(difference / (60 * 1000)), "minute")
  } else if (absoluteDifference < DAY_IN_MILLISECONDS) {
    return relativeFormatter.format(Math.round(difference / (60 * 60 * 1000)), "hour")
  } else if (absoluteDifference < 30 * DAY_IN_MILLISECONDS) {
    return relativeFormatter.format(signedDifferenceInDays(now, date), "day")
  } else if (absoluteDifference < YEAR_IN_MILLISECONDS) {
    return relativeFormatter.format(Math.round(difference / MONTH_IN_MILLISECONDS), "month")
  } else {
    return relativeFormatter.format(Math.round(difference / YEAR_IN_MILLISECONDS), "year")
  }
}

function localDateOrdinal(date) {
  return Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) / DAY_IN_MILLISECONDS
}
